html{text-size-adjust: 100%;}
body{margin: 0px; background: rgb(244, 241, 234); color: rgb(41, 39, 33); font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Heiti SC", system-ui, -apple-system, "Segoe UI", sans-serif; font-size: 16px; line-height: 1.65; font-variant-numeric: tabular-nums;}
p{margin: 0px 0px 12px;}
h1, h2, h3{line-height: 1.25; margin: 0px;}
h2{font-size: 1.45rem; margin: 0px 0px 20px;}
h3{font-size: 1.15rem;}
a{color: rgb(41, 39, 33);}
