[data-system-icon]{display: inline-block; line-height: 1; font-size: 0.95em;}
.wrap{max-width: 1080px; margin: 0px auto; padding: 0px 24px;}
.site-header{background: rgb(244, 241, 234); border-bottom: 1px solid rgb(207, 200, 186);}
.header-inner{display: flex; align-items: center; justify-content: space-between; gap: 16px; height: 64px;}
.brand{font-size: 18px; font-weight: 700; letter-spacing: 0.02em; text-decoration: none; white-space: nowrap;}
.brand:hover{color: rgb(166, 60, 37);}
.site-nav{display: flex; gap: 24px;}
.site-nav a{font-size: 15px; text-decoration: none; padding: 4px 0px; border-bottom: 2px solid transparent;}
.site-nav a:hover{border-bottom-color: rgb(166, 60, 37);}
.hero{padding: 56px 0px 40px; border-bottom: 1px solid rgb(207, 200, 186);}
.hero h1, .page-head h1{font-size: clamp(2rem, 5.2vw, 3.4rem); font-weight: 800; letter-spacing: -0.01em; margin: 0px 0px 16px;}
.page-head{padding: 48px 0px 32px; border-bottom: 1px solid rgb(207, 200, 186);}
.page-head h1{font-size: clamp(1.9rem, 4.6vw, 2.8rem);}
.lead{font-size: clamp(1.05rem, 2vw, 1.3rem); margin: 0px 0px 14px;}
.meta{margin: 0px; font-size: 15px; color: rgb(63, 59, 51); border-left: 3px solid rgb(166, 60, 37); padding-left: 12px;}
.hero-action{margin: 24px 0px 0px;}
.primary-link{display: inline-flex; align-items: center; gap: 8px; background: rgb(166, 60, 37); color: rgb(244, 241, 234); text-decoration: none; font-weight: 600; font-size: 15px; padding: 12px 20px;}
.primary-link:hover{background: rgb(140, 50, 32);}
.section{padding: 56px 0px; border-bottom: 1px solid rgb(207, 200, 186);}
.section:last-child{border-bottom: 0px;}
.section-lead{font-size: 15px; color: rgb(63, 59, 51); margin: 0px 0px 20px; max-width: 44em;}
.section-note{margin: 24px 0px 0px; padding-top: 16px; border-top: 1px solid rgb(207, 200, 186); font-size: 15px; color: rgb(63, 59, 51);}
.band{background: rgb(38, 36, 31); color: rgb(242, 239, 232); padding: 48px 0px;}
.band h2{color: rgb(242, 239, 232);}
.band p{color: rgb(221, 216, 204); margin: 0px 0px 12px; max-width: 46em;}
.band .band-note{color: rgb(242, 239, 232); font-weight: 600; border-left: 3px solid rgb(217, 138, 112); padding-left: 14px; margin: 0px;}
.hours{display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 40px;}
.slot{border-top: 3px solid rgb(166, 60, 37); padding-top: 14px; min-width: 0px;}
.slot-name{margin: 0px 0px 4px; font-size: 15px; color: rgb(63, 59, 51); letter-spacing: 0.1em;}
.slot-time{margin: 0px 0px 6px; font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 700;}
.slot-note{margin: 0px; font-size: 15px; color: rgb(63, 59, 51);}
.index-list{list-style: none; margin: 0px; padding: 0px; border-top: 1px solid rgb(168, 159, 142);}
.index-list li{border-bottom: 1px solid rgb(207, 200, 186);}
.index-list a{display: grid; grid-template-columns: minmax(0px, 1.2fr) minmax(0px, 1fr) auto; grid-template-areas: "name note price"; gap: 4px 16px; align-items: baseline; padding: 14px 0px; text-decoration: none;}
.index-list a:hover .row-name{color: rgb(166, 60, 37);}
.row-name{grid-area: name; font-weight: 600; min-width: 0px;}
.row-note{grid-area: note; font-size: 14px; color: rgb(63, 59, 51);}
.row-price{grid-area: price; color: rgb(166, 60, 37); font-weight: 700; text-align: right; white-space: nowrap;}
.scenes{display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 40px;}
.scene{border-top: 1px solid rgb(168, 159, 142); padding-top: 16px; min-width: 0px;}
.scene h3{margin: 0px 0px 14px;}
.fact-list{display: grid; grid-template-columns: 5.5em minmax(0px, 1fr); gap: 8px 16px; margin: 0px;}
.fact-list dt{color: rgb(63, 59, 51); font-size: 15px;}
.fact-list dd{margin: 0px;}
.split{display: grid; grid-template-columns: 2fr 1fr; gap: 40px; align-items: start;}
.split > *{min-width: 0px;}
.aside{border-top: 2px solid rgb(166, 60, 37); padding-top: 12px; font-size: 15px; color: rgb(63, 59, 51);}
.aside-title{margin: 0px 0px 8px; font-weight: 700; color: rgb(41, 39, 33);}
.timeline{list-style: none; margin: 0px; padding: 0px; border-top: 1px solid rgb(207, 200, 186);}
.timeline li{display: flex; gap: 20px; padding: 10px 0px; border-bottom: 1px solid rgb(207, 200, 186);}
.tl-year{min-width: 5.5em; font-weight: 700; color: rgb(166, 60, 37);}
.line-list{list-style: square; margin: 0px; padding-left: 1.3em;}
.line-list li{padding: 10px 0px; border-bottom: 1px solid rgb(207, 200, 186);}
.line-list li::marker{color: rgb(166, 60, 37);}
.steps{list-style: decimal; margin: 0px; padding-left: 1.6em;}
.steps li{padding: 10px 0px; border-bottom: 1px solid rgb(207, 200, 186);}
.steps li::marker{color: rgb(166, 60, 37); font-weight: 700;}
.dish{margin: 0px 0px 28px; padding-top: 18px; border-top: 1px solid rgb(168, 159, 142);}
.dish-head{display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap;}
.dish-head h3{margin: 0px;}
.dish-price{margin: 0px; font-weight: 700; color: rgb(166, 60, 37); white-space: nowrap;}
.dish-spec{display: grid; grid-template-columns: 5.5em minmax(0px, 1fr); gap: 6px 16px; margin: 12px 0px 0px; font-size: 15px;}
.dish-spec dt{color: rgb(63, 59, 51);}
.dish-spec dd{margin: 0px;}
.combo{border-top: 3px solid rgb(166, 60, 37); padding-top: 16px;}
.combo-name{margin: 0px 0px 4px; font-size: 1.15rem; font-weight: 700;}
.combo-price{margin: 0px 0px 14px; color: rgb(166, 60, 37); font-weight: 700;}
.site-footer{background: rgb(234, 229, 219); border-top: 1px solid rgb(207, 200, 186); padding: 40px 0px;}
.footer-inner{display: grid; grid-template-columns: 1fr 1.3fr; gap: 32px;}
.footer-brand{margin: 0px 0px 8px; font-weight: 700; font-size: 17px;}
.footer-line{margin: 0px 0px 6px; font-size: 14px; color: rgb(63, 59, 51);}
.footer-facts{display: grid; grid-template-columns: auto minmax(0px, 1fr); gap: 6px 16px; margin: 0px; font-size: 14px;}
.footer-facts dt{color: rgb(63, 59, 51);}
